const fs = require('fs');
const lines = fs.readFileSync('/tmp/arena-ws.yCtNWk/transactions.csv', 'utf8').trim().split(/\r?\n/);
const headers = lines[0].split(',');
const rates = Object.fromEntries(fs.readFileSync('/tmp/arena-ws.yCtNWk/rates.csv', 'utf8').trim().split(/\r?\n/).slice(1).map(line => { const [c,r] = line.split(','); return [c, Number(r)]; }));
const rows = lines.slice(1).map(line => {
  const vals = line.split(',');
  const r = Object.fromEntries(headers.map((h,i) => [h, vals[i]]));
  r.cents = Math.round((Number(r.amount) * rates[r.currency] + Number.EPSILON) * 100);
  return r;
});
const total = rows.reduce((s,r)=>s+r.cents,0);
const byMonth = {};
const byCat = {};
for (const r of rows) {
  const m = r.date.slice(0,7);
  byMonth[m] = (byMonth[m] || 0) + r.cents;
  byCat[r.category] = (byCat[r.category] || 0) + r.cents;
}
const max = rows.reduce((a,b)=>a.cents>b.cents?a:b);
console.log(JSON.stringify({count:rows.length,total,average:Math.round(total/rows.length),byMonth,byCat,max:{id:max.id,cents:max.cents},mayVsApril:Math.round(((byMonth['2026-05']/byMonth['2026-04'])-1)*1000)/10,juneVsMay:Math.round(((byMonth['2026-06']/byMonth['2026-05'])-1)*1000)/10,travelShare:Math.round(byCat.travel/total*1000)/10}, null, 2));
